622	/* ---------- resizable tab rail ---------- */
623	(function () {
624	  const handle = $("#railResize");
625	  const root = document.documentElement;
626	  const DEFAULT = 196, MIN = 120, MAX = 560;
627	  const saved = parseInt(localStorage.getItem("railW") || "", 10);
628	  if (saved >= MIN && saved <= MAX) root.style.setProperty("--rail-w", saved + "px");
629	  let dragging = false;
630	  handle.addEventListener("mousedown", (e) => {
631	    dragging = true; handle.classList.add("dragging");
632	    document.body.classList.add("col-resizing"); e.preventDefault();
633	  });
634	  window.addEventListener("mousemove", (e) => {
635	    if (!dragging) return;
636	    root.style.setProperty("--rail-w", Math.max(MIN, Math.min(MAX, e.clientX)) + "px");
637	  });
638	  window.addEventListener("mouseup", () => {
639	    if (!dragging) return;
640	    dragging = false; handle.classList.remove("dragging");
641	    document.body.classList.remove("col-resizing");
642	    const cur = parseInt(getComputedStyle(root).getPropertyValue("--rail-w"), 10);
643	    if (cur) localStorage.setItem("railW", cur);
644	  });
645	  handle.addEventListener("dblclick", () => {
646	    root.style.setProperty("--rail-w", DEFAULT + "px");
647	    localStorage.setItem("railW", DEFAULT);
648	  });
649	})();
