function renderTabs() {
  tabsEl.innerHTML = "";
  const list = sortedSessions();
  const anyPinned = list.some((s) => s.pinned);
  let section = null;   // which header we've emitted so far: "pinned" | "recent"
  list.forEach((s) => {
    if (anyPinned) {
      const want = s.pinned ? "pinned" : "recent";
      if (want !== section) {
        const h = el("div", "tabsection" + (s.pinned ? " pinned" : ""),
